package com.giovannielena.restaurant.config;
import com.giovannielena.restaurant.entity.User; import com.giovannielena.restaurant.repository.UserRepository; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class AdminBootstrap { @Bean CommandLineRunner createAdmin(UserRepository users,PasswordEncoder encoder,@Value("${ADMIN_EMAIL:}") String email,@Value("${ADMIN_PASSWORD:}") String password,@Value("${ADMIN_NAME:Restaurant Admin}") String name){return args->{if(!email.isBlank()&&!password.isBlank()&&!users.existsByEmail(email.toLowerCase())){User u=new User();u.setFullName(name);u.setEmail(email.toLowerCase());u.setPassword(encoder.encode(password));u.setRole(User.Role.ADMIN);users.save(u);}};} }